// server/middleware/quoteCache.ts
import { LRUCache } from "lru-cache";
var quoteCache = new LRUCache({
  max: 500,
  // Store up to 500 quotes
  ttl: 1e3 * 60 * 10,
  // 10 minutes
  updateAgeOnGet: true
  // Refresh TTL on cache hit
});
function getCacheKey(params) {
  return `${params.serviceType}:${params.propertyType}:${Math.round(params.propertySize)}`;
}
function quoteCacheMiddleware(req, res, next) {
  try {
    const { serviceType, propertyType, propertySize } = req.body;
    if (!serviceType || !propertyType || !propertySize) {
      return next();
    }
    const cacheKey = getCacheKey({ serviceType, propertyType, propertySize });
    const cached = quoteCache.get(cacheKey);
    if (cached) {
      console.log(`[Cache HIT] ${cacheKey}`);
      return res.json({
        ...cached,
        cached: true
        // Add flag to indicate cache hit
      });
    }
    console.log(`[Cache MISS] ${cacheKey}`);
    const originalJson = res.json.bind(res);
    res.json = function(data) {
      if (data.success !== false) {
        quoteCache.set(cacheKey, data);
        console.log(`[Cache SET] ${cacheKey}`);
      }
      return originalJson(data);
    };
    next();
  } catch (error) {
    console.error("Cache middleware error:", error);
    next();
  }
}

